    texCoord = vec2(0.0);
    glColor = gl_Color;
    mat = dhMaterialId == DH_BLOCK_WATER ? 32000 : (dhMaterialId == DH_BLOCK_LEAVES ? 10003 : 0);
    position = shadowModelViewInverse * gl_ModelViewMatrix * gl_Vertex;
#ifdef WORLD_CURVATURE
